"""Typed PAY model, argument-order code and payment rule."""
import sys,json
from pathlib import Path
sys.dont_write_bytecode=True;p=Path(__file__).resolve().parents[2];sys.path.insert(0,str(p/'skoolkit-10.1'))
from skoolkit.traceutils import disassemble
from skoolkit.z80 import Assembler
m=bytes(0x5d80)+(p/'sherlock-analisi/block-10.bin').read_bytes();asm=Assembler()
regions=[(0x8379,0x8381,'data','Modello PAY: TO opzionale e ruoli dativi'),(0xb39d,0xb405,'code','Ricerca del modello lessicale prima dei ruoli degli argomenti'),(0xb405,0xb468,'code','Ordinamento semantico: senza TO destinatario prima dell’importo'),(0xb468,0xb483,'code','Copia dei nominali nei ruoli senza alterare il nodo sintattico'),(0xe345,0xe370,'code','Preflight del saldo e rifiuto del pagamento'),(0xe370,0xe374,'data','Intestazione PAY: letterale monetario e persona destinataria'),(0xe374,0xe38f,'code','Corpo del pagamento: addebito e accredito')]
notes={0x8379:'Quattro word del modello37 con flag nei nibble alti: PAY/TO. A01D=0C,A01E=2D. Non è codice; anche l’assenza della preposizione passa alla scelta dei ruoli.',0xb3eb:'Confronta il modello lessicale; gli argomenti monetari o mancanti non giustificano un modello sconosciuto inventato dal prototipo.',0xb405:'Lo scambio dei ruoli è guidato dal modello e dalla preposizione, non dal test euristico “il secondo nominale sembra denaro”.',0xb421:'Preposizione assente: usa A01E, poi XOR20. PAY legge destinatario, importo anche se uno dei due nominali manca.',0xb445:'La selezione degli offset del nodo non muta i due gruppi sintattici. Conservare gli slot fisici e il loro ordine nell’arena.',0xb449:'Offset12/08 oppure08/12 per primo/secondo ruolo. Un importo scritto da solo non diventa automaticamente un pagamento al personaggio vicino.',0xb468:'Copia sei byte del nominale selezionato; anche uno slot vuoto partecipa alla semantica.',0xe345:'Il predicato del pagamento richiede il saldo disponibile; il corpo non è raggiunto quando la semantica precedente rifiuta gli argomenti.',0xe34f:'Cerca il conto del soggetto corrente; E619 restituisce il descrittore del denaro, oppure Z se manca.',0xe35a:'Decodifica il letterale monetario A02F prima del confronto con il saldo.',0xe35e:'Sottrae l’importo dal saldo: carry indica fondi insufficienti e sceglie il ritorno di fallimento.',0xe377:'Scrive il saldo residuo del pagante nel formato originale.',0xe37d:'Cerca il conto del destinatario. Se manca, il corpo originale salta l’accredito e termina; questo dossier non modifica tale meccanica.',0xe388:'Somma l’importo al saldo del conto destinatario trovato.',0xe36a:'Testo di insufficienza fondi disponibile al motore; non è il messaggio visibile in ogni rifiuto semantico PAY.',0xe370:'Header66,1D con predicatoE345: classe6 letterale monetario, classe13 persona percepibile; costo1. Non decodificare come istruzioni.',0xe374:'Il trasferimento resta lo stesso per PAY destinatario importo e PAY importo TO destinatario. PAY10D da solo non arriva al corpo e non avanza il tempo.'}
fields=[['Modello','37 /8379','PAY con TO opzionale; flags0C/2D'],['Con TO','importo TO destinatario','Ordine canonico'],['Senza TO','destinatario importo','Scambio semantico anche per slot vuoti; nodo fisico intatto'],['PAY10D',"DON'T BE SILLY.",'Nessun destinatario implicito, nessun turno pagato, nessuna continuation']]
lines=['; Dossier PAY: modello e intestazione sono dati; istruzioni riasssemblate contro il payload.'];count=total=0
for a,b,kind,label in regions:
 lines+=['',f'    ORG ${a:04X}',f'; {kind.upper()}: {label}'];at=a
 while at<b:
  if kind=='data':n=min(8,b-at);op='DEFB '+','.join(f'${v:02X}'for v in m[at:at+n])
  else:op,n=disassemble(m,at);count+=1
  assert at+n<=b,(hex(at),op);assert bytes(asm.assemble(op,at))==m[at:at+n]
  lines.append(f'    {op:<37} ; ${at:04X} {m[at:at+n].hex(" ")}'+(' | '+notes[at]if at in notes else''));at+=n;total+=n
root=p/'sherlock-js/results/pay-omitted-to';(root/'pay-order.asm').write_text('\n'.join(lines)+'\n');(root/'listing-verification.json').write_text(json.dumps(dict(roundtrip_equal=True,instructions=count,bytes_roundtripped=total,regions=[dict(start=f'{a:04X}',end_exclusive=f'{b:04X}',kind=k,label=l,atlas_priority=147,**({'fields':fields}if a==0x8379 else{}))for a,b,k,l in regions]),indent=2,ensure_ascii=False)+'\n');print(count,total)
